#!/usr/bin/env bun
//
// What the app's port of `scene.ts`, `WordmarkScene.swift`, is held to: every window as `windows(t)`
// draws it at two instants of each step, early in its motion and as it lands, for `WordmarkSceneTests`.
//
//   bun golden.ts                     Tests/EmiraShellTests/WordmarkGolden.swift
//
// `bun run ship` runs it, so a change to the loop reaches the app as a failing test until the port
// agrees.

import { join } from "node:path";
import { SCRIPT, windows } from "./scene.ts";

const out = join(import.meta.dir, "../../Tests/EmiraShellTests/WordmarkGolden.swift");

const f = (n: number) => String(+n.toFixed(4));

const instants: number[] = [];
let start = 0;
for (const step of SCRIPT) {
    instants.push(start + 0.08, start + step.hold - 0.001);
    start += step.hold;
}

const rows = instants.map((t) => {
    const drawn = windows(t).map(({ letter, x, y, w, h, r, o, gx, gy, k }) =>
        `            Drawn(.${letter}, ${[x, y, w, h, r, o, gx, gy, k].map(f).join(", ")}),`);
    return `        Instant(${f(t)}, [\n${drawn.join("\n")}\n        ]),`;
});

await Bun.write(out, `// Generated by \`.github/logo/golden.ts\` from \`scene.ts\`. \`bun run ship\` rewrites it; don't edit it.
// Each window: letter, x, y, w, h, corner radius, opacity, glyph x, glyph y, glyph scale — in draw order.

@testable import EmiraShell

extension WordmarkSceneTests {
    static let golden: [Instant] = [
${rows.join("\n")}
    ]
}
`);

console.log(`logo: wrote ${out} — ${instants.length} instants`);
